        {
          h: '隋朝的灭亡与唐朝的建立',
          html: `<p>隋朝只存在了 30 多年（581—618 年），是个短命王朝。主要原因在隋炀帝的<b>暴政</b>：</p>
<ul><li>大兴土木，营建东都洛阳，开凿运河，征发大量民力；</li>
<li>多次发动对外战争（三次出兵高丽），兵役、徭役沉重；</li>
<li>生活奢侈，多次出巡，挥霍无度。</li></ul>
<p>百姓无法生存，各地爆发农民起义，其中瓦岗军是一支重要力量。618 年，隋炀帝在江都（今江苏扬州）被部下杀死，隋朝灭亡。同年，<b>李渊</b>在长安称帝，建立<b>唐朝</b>，定都<b>长安</b>，他就是唐高祖。</p>
<div class="key">隋亡于暴政。开凿大运河本身有利于南北交流，但隋炀帝急于求成、滥用民力，加重了百姓负担。</div>
<p>唐朝诗人皮日休这样看待大运河：</p>
<div class="source">尽道隋亡为此河，至今千里赖通波。若无水殿龙舟事，共禹论功不较多。<span class="from">——〔唐〕皮日休《汴河怀古》</span></div>
<p>意思是：人们都说隋朝因为这条运河灭亡，可直到今天千里航运还依赖它；要是没有隋炀帝乘龙舟巡游的奢侈之事，他开运河的功劳几乎可以和大禹治水相比。可见评价历史事件要<b>一分为二</b>。</p>`
        },
        {
          h: '唐太宗与“贞观之治”',
          html: `<p>626 年，李世民即位，就是<b>唐太宗</b>，年号“贞观”。他亲眼看到隋朝由强盛到迅速灭亡，常以<b>隋亡为戒</b>，认识到百姓的力量：</p>
<div class="source">舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟。<span class="from">——《贞观政要》</span></div>
<p>唐太宗的主要措施：</p>
<ul><li><b>发展生产</b>：重视农业，减轻农民的徭役和赋税负担；</li>
<li><b>整顿吏治</b>：精简中央机构，完善三省六部制；</li>
<li><b>任用贤才、虚心纳谏</b>：重用房玄龄、杜如晦等人；魏征敢于直言进谏，唐太宗多能接受；</li>
<li><b>发展科举</b>，扩充国学，培养人才；</li>
<li>实行比较开明的民族政策（下一个知识点详讲）。</li></ul>
<p>魏征去世后，唐太宗感叹：</p>
<div class="source">夫以铜为镜，可以正衣冠；以古为镜，可以知兴替；以人为镜，可以明得失。<span class="from">——《旧唐书·魏徵传》</span></div>
<p>唐太宗统治时期，政治比较清明，经济得到发展，国力逐步增强，历史上称为<b>“贞观之治”</b>。</p>
<div class="key">贞观之治 = 唐太宗 ＋ 以隋亡为戒 ＋ 重农轻徭、任贤纳谏、整顿吏治 → 政治清明、经济发展、国力增强。</div>
<p class="warn">“三省六部制”的分工：中书省起草诏令，门下省审核，尚书省执行，尚书省下设六部。它在隋朝确立，唐太宗时进一步完善。</p>`
        }
