          h: '海外贸易与对外交流：泉州港与马可·波罗',
          html: `<p>宋元时期，海外贸易空前繁荣，“海上丝绸之路”十分兴盛。</p>
<p><b>为什么海外贸易发达？</b>造船技术先进；指南针应用于航海；政府重视海外贸易，在广州、<b>泉州</b>、明州（今浙江宁波）等港口设立<b>市舶司</b>，管理海外贸易、征收关税。</p>
<p><b>泉州港。</b>北宋时（1087 年），朝廷在泉州设立市舶司。南宋和元朝时，泉州港十分繁荣，外国商人称泉州为“刺桐”。元朝时来华的马可·波罗把它描述为世界上最大的港口之一。泉州至今还保存着清净寺等许多宋元时期海外交往的遗迹。2021 年，“<b>泉州：宋元中国的世界海洋商贸中心</b>”被列入《世界遗产名录》。</p>
<p>宋元时期，中国同日本、高丽以及东南亚、南亚、阿拉伯地区和非洲东海岸等地都有贸易往来。出口的主要商品有丝织品、瓷器、茶叶等。</p>
<p><b>马可·波罗。</b>意大利人马可·波罗于元朝时来到中国，在中国生活了十几年。他回国后，有人根据他的口述写成《马可·波罗行纪》（又名《马可·波罗游记》），书中描述了中国的富庶繁荣，激发了欧洲人对东方的向往。</p>
<div class="key">宋元时期海外贸易空前繁荣，政府设市舶司管理海外贸易；泉州是当时世界著名的大港。</div>`
